import {TYPE_LABELS} from './letters-core.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const kinds={template:'模板',history:'历史函件',rule:'规范要点',reference:'参考资料'};
const category=d=>({outgoing:'发函模板参考',incoming:'复函参考',support:'支撑材料'}[d.metadata.direction]||kinds[d.kind]||d.kind);
const status=d=>d.metadata.extractionError?'识别待处理':d.chunks?(d.enabled?'已索引 · 已启用':'已索引 · 已停用'):'已归档 · 未向量化';
const displayTitle=d=>d.title.replace(/^(?:发函模板参考|复函参考|支撑材料)\s*·\s*/, '');
const sourceLocation=d=>(d.metadata.source||d.metadata.name||'').replace(/\/[^/]+$/, '');
const stateLabel=d=>d.metadata.extractionError?'识别待处理':d.chunks?(d.enabled?'检索已启用':'检索已停用'):'仅本机归档';
const stateClass=d=>d.metadata.extractionError?'warning':d.chunks&&d.enabled?'active':'archived';
const typeOptions=()=>'<option value="all">全部类型</option>'+Object.entries(TYPE_LABELS).map(([v,n])=>`<option value="${v}">${n}</option>`).join('');
export const knowledgePanel=()=>'<section class="panel knowledge-panel" id="knowledge-panel"><div class="bodypad">正在读取数据库与知识资料…</div></section>';
export async function loadKnowledgePanel({config,context,modal,toast}){
 const host=document.getElementById('knowledge-panel');if(!host)return;
 const api=async(body)=>{const r=await fetch((config.baseUrl||'http://127.0.0.1:4318')+'/api/v1/knowledge',{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(240000)});const v=await r.json();if(!r.ok)throw new Error(v.error?.message||'知识资料接口失败');return v;};
 const showError=error=>{const node=document.getElementById('knowledge-error');if(node)node.textContent=error.message;toast?.(error.message);};
 let data;
 try{data=await api()}catch(error){if(host.isConnected)host.innerHTML='<div class="bodypad error-msg">'+esc(error.message)+'</div>';return;}
 if(!host.isConnected)return;
 const cfg=data.settings;
 host.innerHTML=`<div class="panel-head"><div><b>知识资料库</b><span class="tag ${cfg.database?'':'amber'}">${cfg.database?'PostgreSQL · pgvector':'尚未连接数据库'}</span><span class="tag gray">${cfg.enabled?'起草时检索已启用':'起草时检索未启用'}</span></div><div class="actions"><button id="knowledge-settings">检索设置</button><button id="knowledge-sync" ${cfg.database?'':'disabled'}>同步有效模板</button><button id="knowledge-add" class="primary" ${cfg.database?'':'disabled'}>添加资料</button></div></div><div class="bodypad"><p class="muted">共 ${data.documents.length} 份资料 · ${data.documents.filter(d=>d.enabled&&d.chunks).length} 份检索启用 · ${data.documents.reduce((n,d)=>n+d.chunks,0)} 个向量片段。向量模型：${esc(cfg.model)}。</p><div id="knowledge-error" class="error-msg" role="status"></div><div class="knowledge-search"><input id="knowledge-query" aria-label="检索知识资料" placeholder="例如：线路跨越公路需要征询哪些意见"><select id="knowledge-type" aria-label="检索协议类型">${typeOptions()}</select><button id="knowledge-search" ${cfg.database?'':'disabled'}>检索测试</button></div><div id="knowledge-results"></div><div class="knowledge-search"><input id="knowledge-filter" aria-label="筛选资料名称" placeholder="按名称或来源筛选资料（不调用模型）"><select id="knowledge-category" aria-label="筛选资料类别"><option value="all">全部资料</option><option value="outgoing">发函模板参考</option><option value="incoming">复函参考</option><option value="support">支撑材料</option><option value="template">内置模板</option></select></div></div><div class="table-wrap knowledge-table-wrap"><table class="knowledge-table" aria-label="知识资料列表"><colgroup><col class="knowledge-name-col"><col class="knowledge-type-col"><col class="knowledge-status-col"><col class="knowledge-actions-col"></colgroup><thead><tr><th scope="col">资料名称 / 来源</th><th scope="col">类别 / 适用类型</th><th scope="col">检索状态</th><th scope="col">操作</th></tr></thead><tbody id="knowledge-rows"></tbody></table></div><nav class="knowledge-pagination" aria-label="知识资料分页"><span id="knowledge-count" class="knowledge-page-count"></span><div class="knowledge-page-controls"><button id="knowledge-prev">上一页</button><span id="knowledge-page" aria-live="polite"></span><button id="knowledge-next">下一页</button></div></nav>`;
 const reload=()=>loadKnowledgePanel({config,context,modal,toast});
 host.querySelector('#knowledge-sync').onclick=async event=>{try{event.target.disabled=true;event.target.textContent='正在向量化…';const r=await api({action:'sync-templates'});toast?.('已同步 '+r.documents+' 份有效模板');await reload();}catch(e){showError(e);event.target.disabled=false;event.target.textContent='同步有效模板';}};
 let page=0;
 const renderRows=()=>{
  const query=host.querySelector('#knowledge-filter').value.trim().toLowerCase(),kind=host.querySelector('#knowledge-category').value;
  const docs=data.documents.filter(d=>(kind==='all'||d.metadata.direction===kind||kind==='template'&&d.kind==='template')&&[d.title,d.metadata.source].join(' ').toLowerCase().includes(query));
  const pages=Math.max(1,Math.ceil(docs.length/15));page=Math.min(page,pages-1);
  host.querySelector('#knowledge-rows').innerHTML=docs.slice(page*15,page*15+15).map(d=>`<tr><td><strong class="knowledge-name" title="${esc(d.title)}">${esc(displayTitle(d))}</strong><small class="knowledge-source" title="${esc(d.metadata.source||d.metadata.name||'')}">${esc(sourceLocation(d)||d.metadata.source||d.metadata.name||'')}</small></td><td><span class="knowledge-category-name">${esc(category(d))}</span><span class="knowledge-type-name">${esc(TYPE_LABELS[d.consultation_type]||'全部类型')}</span><small>${esc(d.project_id?d.project_id+' · '+d.project_version:'通用参考')}</small></td><td><span class="knowledge-state ${stateClass(d)}">${esc(stateLabel(d))}</span><small>${d.chunks?d.chunks+' 个向量片段':'未建立向量索引'}</small>${d.metadata.method==='ocr'?'<small class="knowledge-ocr">OCR文字待核对</small>':''}</td><td><div class="knowledge-row-actions"><button class="small" data-knowledge-detail="${esc(d.id)}">查看资料</button>${d.chunks?`<button class="small knowledge-secondary-action" data-knowledge-toggle="${esc(d.id)}">${d.enabled?'停用':'启用'}</button>`:d.metadata.direction==='outgoing'&&!d.metadata.extractionError?`<button class="small knowledge-secondary-action" data-knowledge-index="${esc(d.id)}">建立索引</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="4" class="knowledge-no-results">没有匹配的资料。</td></tr>';
  host.querySelector('#knowledge-count').textContent=`共 ${docs.length} 份资料`;
  host.querySelector('#knowledge-page').textContent=`第 ${page+1} / ${pages} 页`;
  host.querySelector('#knowledge-prev').disabled=page===0;host.querySelector('#knowledge-next').disabled=page===pages-1;
  for(const button of host.querySelectorAll('[data-knowledge-toggle]'))button.onclick=async()=>{try{const doc=data.documents.find(d=>d.id===button.dataset.knowledgeToggle);await api({action:'set-enabled',id:doc.id,enabled:!doc.enabled});doc.enabled=!doc.enabled;renderRows();}catch(e){showError(e);}};
  const openDocument=async(id,indexing=false)=>{try{
   const d=await api({action:'detail',id});
   modal(indexing?'建立发函参考索引':'查看知识资料',`<h3>${esc(d.title)}</h3><p>${esc(category(d))} · ${esc(d.metadata.review||'')} · ${esc(status(data.documents.find(x=>x.id===id)))}</p><p class="muted">${esc(d.metadata.source||d.metadata.name||'')}</p>${d.metadata.archived?`<a href="${esc((config.baseUrl||'http://127.0.0.1:4318')+'/api/v1/knowledge/'+encodeURIComponent(id)+'/original')}" download>下载原文件</a>`:''}${indexing?`<p>将以下去掉联系信息的发函片段发送至 ${esc(cfg.baseUrl)}，使用 ${esc(cfg.model)} 建立检索索引。原文件保留在本机。</p>`:''}<pre class="knowledge-excerpt knowledge-document">${esc(indexing?d.index_text:d.content||'该旧索引仅保存了片段，模板结构可在函件模板管理中查看。')}</pre><div id="knowledge-detail-error" class="error-msg" role="status"></div>`,`<button data-action="close">关闭</button>${indexing?'<button class="primary" id="knowledge-confirm-index">确认建立索引</button>':''}`,true);
   if(indexing)document.getElementById('knowledge-confirm-index').onclick=async event=>{try{event.target.disabled=true;event.target.textContent='正在向量化…';await api({action:'index',id});document.getElementById('dialog').close();toast?.('索引已建立，起草时可检索使用');await reload();}catch(e){document.getElementById('knowledge-detail-error').textContent=e.message;event.target.disabled=false;event.target.textContent='确认建立索引';}};
  }catch(e){showError(e);}};
  for(const b of host.querySelectorAll('[data-knowledge-detail]'))b.onclick=()=>openDocument(b.dataset.knowledgeDetail);
  for(const b of host.querySelectorAll('[data-knowledge-index]'))b.onclick=()=>openDocument(b.dataset.knowledgeIndex,true);
 };
 host.querySelector('#knowledge-filter').oninput=()=>{page=0;renderRows()};host.querySelector('#knowledge-category').onchange=()=>{page=0;renderRows()};
 host.querySelector('#knowledge-prev').onclick=()=>{page--;renderRows()};host.querySelector('#knowledge-next').onclick=()=>{page++;renderRows()};renderRows();
 host.querySelector('#knowledge-search').onclick=async event=>{try{event.target.disabled=true;const r=await api({action:'search',query:host.querySelector('#knowledge-query').value,type:host.querySelector('#knowledge-type').value,projectId:context.project.id||'',projectVersion:context.project.version||''});host.querySelector('#knowledge-results').innerHTML=r.sources.length?r.sources.map(s=>`<div class="checkcard"><b>${esc(s.title)} · 相关度 ${(s.score*100).toFixed(1)}%</b><pre class="knowledge-excerpt">${esc(s.content)}</pre></div>`).join(''):'<p class="muted">没有匹配到有效资料，请检查适用类型、工程范围或索引使用的向量模型。</p>';}catch(e){showError(e)}finally{event.target.disabled=false}};
 host.querySelector('#knowledge-settings').onclick=()=>{
  modal('知识检索设置',`<label class="checklabel"><input id="rag-enabled" type="checkbox" ${cfg.enabled?'checked':''}>起草正文时检索参考资料</label><label class="field"><span>向量模型名称</span><input id="rag-model" value="${esc(cfg.model)}"></label><div class="field-row"><label class="field"><span>向量维度</span><select id="rag-dimensions">${[64,128,256,512,768,1024,1536,2048].map(n=>`<option ${cfg.dimensions===n?'selected':''}>${n}</option>`).join('')}</select></label><label class="field"><span>每次检索片段数</span><input id="rag-topk" type="number" min="1" max="8" value="${cfg.topK}"></label></div><p class="muted">沿用大模型配置中的服务地址和密钥。修改向量模型或维度后，需要重新同步模板或入库资料。</p><div id="rag-message" class="error-msg" role="status"></div>`,`<button data-action="close">关闭</button><button id="rag-test">测试已保存配置</button><button id="rag-save" class="primary">保存</button>`,true);
  document.getElementById('rag-save').onclick=async()=>{try{await api({action:'configure',enabled:document.getElementById('rag-enabled').checked,model:document.getElementById('rag-model').value,dimensions:Number(document.getElementById('rag-dimensions').value),topK:Number(document.getElementById('rag-topk').value)});document.getElementById('rag-message').textContent='检索配置已保存';await reload();}catch(e){document.getElementById('rag-message').textContent=e.message}};
  document.getElementById('rag-test').onclick=async event=>{try{event.target.disabled=true;document.getElementById('rag-message').textContent='正在测试向量模型…';const r=await api({action:'test'});document.getElementById('rag-message').textContent='连接成功：'+r.model+' · '+r.dimensions+'维';}catch(e){document.getElementById('rag-message').textContent=e.message}finally{event.target.disabled=false}};
 };
 host.querySelector('#knowledge-add').onclick=()=>{
  modal('添加知识资料',`<label class="field"><span>资料名称</span><input id="kd-title" placeholder="不填时使用文件名"></label><div class="field-row"><label class="field"><span>资料类别</span><select id="kd-kind"><option value="reference">参考资料</option><option value="history">历史函件</option><option value="rule">规范要点</option></select></label><label class="field"><span>适用协议类型</span><select id="kd-type">${typeOptions()}</select></label><label class="field"><span>适用工程</span><select id="kd-scope"><option value="global">通用资料</option><option value="project" ${context.project.id?'':'disabled'}>仅当前工程与版本</option></select></label></div><label class="field"><span>选择文件（PDF / Word / TXT / Markdown，最大10MB）</span><input id="kd-file" type="file" accept=".pdf,.docx,.doc,.txt,.md"></label><label class="field"><span>或粘贴资料文字</span><textarea id="kd-text" rows="6" placeholder="文件和文字二选一"></textarea></label><p class="muted">入库时调用向量模型解析后的文字；扫描PDF需先完成OCR。</p><div id="kd-message" class="error-msg" role="status"></div>`,`<button data-action="close">取消</button><button id="kd-save" class="primary">解析并入库</button>`,true);
  document.getElementById('kd-save').onclick=async event=>{try{
   event.target.disabled=true;const file=document.getElementById('kd-file').files[0],text=document.getElementById('kd-text').value;
   if(!file&&!text.trim())throw new Error('请选择文件或粘贴资料文字');if(file&&text.trim())throw new Error('文件和文字请选择一种输入方式');
   const project=document.getElementById('kd-scope').value==='project';const b={action:'ingest',title:document.getElementById('kd-title').value||file?.name,kind:document.getElementById('kd-kind').value,type:document.getElementById('kd-type').value,projectId:project?context.project.id:'',projectVersion:project?context.project.version:''};
   if(file){if(file.size>10*1024*1024)throw new Error('单文件不能超过10MB');const bytes=new Uint8Array(await file.arrayBuffer());let raw='';for(let i=0;i<bytes.length;i+=32768)raw+=String.fromCharCode(...bytes.subarray(i,i+32768));Object.assign(b,{name:file.name,base64:btoa(raw)});}else b.text=text;
   document.getElementById('kd-message').textContent='正在解析并向量化，请稍候…';const r=await api(b);document.getElementById('dialog').close();toast?.(r.reused?'该资料已入库，已复用现有记录':'入库完成，共 '+r.chunks+' 个片段');await reload();
  }catch(e){document.getElementById('kd-message').textContent=e.message;event.target.disabled=false}};
 };
}
